const cardPoint = await page.$eval(".pagelink", (e) => { const r = e.getBoundingClientRect(); return [r.right - 20, r.top + r.height / 2]; });
const cardUrl = page.url(); await page.mouse.click(...cardPoint); await new Promise((r) => setTimeout(r, 150));
ok(page.url() === cardUrl && !(await page.$eval("#filterPanel", (e) => !e.hidden)), "clicking a blurred card only closes the panel");
await page.waitForFunction(() => !getComputedStyle(document.querySelector("#profiles")).filter.includes("blur")); ok(true, "the blur clears when the panel closes");
await page.click("#sortBtn"); await page.waitForSelector("#sortPanel:not([hidden])"); ok(await blurred(), "the cards blur behind an open sort panel");
await page.keyboard.press("Escape"); await page.waitForFunction(() => !getComputedStyle(document.querySelector("#profiles")).filter.includes("blur")); ok(true, "Escape clears the blur");
await page.click("#filterBtn"); await page.waitForSelector("#filterPanel:not([hidden])");
await page.mouse.click(5, 5); ok(!(await page.$eval("#filterPanel", (e) => !e.hidden)), "clicking away closes the filter panel");
pp("publish", second.id, "--status", "open");
await page.goto(base + "/probes", { waitUntil: "networkidle0" }); await page.waitForSelector(".profile.single .who");
await Promise.all([page.waitForNavigation({ waitUntil: "networkidle0" }), page.click(".profile.single .who")]);
ok(new URL(page.url()).pathname.split("/").length === 4, "clicking anywhere on a probe card opens the page");
const brand = await page.$(".brandlink"); const before = await page.$eval(".brandlink", (e) => { const r = e.getBoundingClientRect(); return [r.width, r.height, getComputedStyle(e).fontSize, getComputedStyle(e).transform]; });
await brand.hover();
ok((await page.$eval(".brandlink", (e) => getComputedStyle(e).animationName)) === "rainbow", "the ProofProbe link shimmers on hover");
ok(JSON.stringify(await page.$eval(".brandlink", (e) => { const r = e.getBoundingClientRect(); return [r.width, r.height, getComputedStyle(e).fontSize, getComputedStyle(e).transform]; })) === JSON.stringify(before), "hovering the ProofProbe link never resizes or rescales it");

const paint = await browser.newPage();
await paint.setRequestInterception(true);
paint.on("request", (r) => { if (r.url().includes("/api/pages/")) setTimeout(() => r.continue(), 900); else r.continue(); });
await paint.goto(first.link, { waitUntil: "domcontentloaded" });
ok((await paint.$("#loadbar")) && (await paint.$("#skel")), "the loading bar shows before content arrives");
await paint.waitForSelector("#viewQs:not([hidden])"); await paint.waitForFunction(() => !document.querySelector("#loadbar"));
ok(!(await paint.$("#skel")), "the loading bar clears when content arrives"); await paint.close();
await page.goto(first.link, { waitUntil: "networkidle0" }); await page.waitForSelector("#acctBtn");
ok((await shown("#viewQs")) && !(await shown("#qBox")) && (await page.$$("#form textarea")).length === 0, "a visitor gets a read-only page");
await page.evaluate(() => scrollTo(0, document.documentElement.scrollHeight)); await new Promise((r) => setTimeout(r, 120));
