const pinned = async (w, h) => { await page.setViewport({ width: w, height: h }); await page.evaluate(() => scrollTo(0, document.documentElement.scrollHeight)); await new Promise((r) => setTimeout(r, 150)); return page.evaluate(() => { const p = document.querySelector("#acct").getBoundingClientRect(), b = document.querySelector(".bar").getBoundingClientRect(); return p.top >= 0 && p.top < 30 && p.right <= innerWidth && p.left >= 0 && (b.bottom <= p.top || b.top >= p.bottom - 1 || b.height === 0); }); };
